<?php
$id=trim($_GET['id']??'');if($id===''){http_response_code(400);echo json_encode(['success'=>false,'error'=>'Peptide ID required']);exit;}
$s=$pdo->prepare("SELECT p.*,GROUP_CONCAT(DISTINCT so.scientific_name SEPARATOR ' | ') scientific_names,GROUP_CONCAT(DISTINCT so.venom_group SEPARATOR ', ') venom_groups FROM peptides p LEFT JOIN peptide_sources ps ON p.peptide_id=ps.peptide_id LEFT JOIN source_organisms so ON ps.organism_id=so.organism_id WHERE p.public_id=:id GROUP BY p.peptide_id");$s->execute([':id'=>$id]);$p=$s->fetch();if(!$p){http_response_code(404);echo json_encode(['success'=>false,'error'=>'Peptide not found']);exit;}
foreach([['activity',"SELECT aa.*,cl.cell_line_name,cl.species,ct.cancer_name,pub.pmid,pub.title FROM activity_assays aa LEFT JOIN cell_lines cl ON aa.cell_line_id=cl.cell_line_id LEFT JOIN cancer_types ct ON cl.cancer_type_id=ct.cancer_type_id LEFT JOIN publications pub ON aa.publication_id=pub.publication_id WHERE aa.peptide_id=?"],['mechanisms',"SELECT pm.*,m.mechanism_name,cl.cell_line_name,pub.pmid,pub.title FROM peptide_mechanisms pm JOIN mechanisms m ON pm.mechanism_id=m.mechanism_id LEFT JOIN cell_lines cl ON pm.cell_line_id=cl.cell_line_id LEFT JOIN publications pub ON pm.publication_id=pub.publication_id WHERE pm.peptide_id=?"],['structures','SELECT * FROM structures WHERE peptide_id=?'],['publications',"SELECT DISTINCT pub.* FROM publications pub LEFT JOIN activity_assays aa ON pub.publication_id=aa.publication_id LEFT JOIN peptide_mechanisms pm ON pub.publication_id=pm.publication_id WHERE aa.peptide_id=? OR pm.peptide_id=?"]] as $x){$s=$pdo->prepare($x[1]);$s->execute($x[0]==='publications'?[$p['peptide_id'],$p['peptide_id']]:[$p['peptide_id']]);${$x[0]}=$s->fetchAll();}
$seq=$p['sequence']??'';$aa=[];if($seq){foreach(str_split($seq) as $a)$aa[$a]=($aa[$a]??0)+1;arsort($aa);} $hyd=['A','I','L','M','F','W','V','Y'];$hydN=0;foreach(str_split($seq) as $a)if(in_array($a,$hyd,true))$hydN++;$comp=[];foreach($aa as $a=>$n)$comp[$a]=round($n/max(1,strlen($seq))*100,1);
echo json_encode(['success'=>true,'peptide'=>['identity'=>$p,'activity'=>$activity,'mechanisms'=>$mechanisms,'structures'=>$structures,'publications'=>$publications,'sequence_analysis'=>['length'=>strlen($seq),'composition'=>$comp,'hydrophobic_fraction'=>strlen($seq)?round($hydN/strlen($seq),3):null,'cysteine_count'=>substr_count($seq,'C')],'evidence_completeness'=>['sequence_verified'=>$p['sequence_source_status']!=='Unavailable','activity_records'=>count($activity),'mechanism_records'=>count($mechanisms),'pdb_available'=>count($structures)>0,'linked_publications'=>count($publications)]]]);
